    "0-12": { status: 'C', statusFull: "Dies Comitialis", deity: "Júpiter", deityDesc: "Júpiter.", festivalName: "Día Cívico de Júpiter", festivalDesc: "Júpiter como garante supremo de los juramentos presenciales. Las transacciones y promesas públicas gozan de su respaldo sagrado." },
