    "0-14": { status: 'EN', statusFull: "Dies Endotercissus", deity: "Felicitas", deityDesc: "Buena suerte.", festivalName: "Día de Felicitas", festivalDesc: "Día Endotercissus dedicado a la Buena Fortuna. La mañana y la tarde pueden dedicarse al negocio, pero el mediodía es tiempo sagrado." },
