    "0-16": { status: 'C', statusFull: "Dies Comitialis", deity: "Concordia", deityDesc: "Armonía.", festivalName: "Dedicación Templo Concordia", festivalDesc: "Se conmemora la dedicación del Templo de la Concordia, erigido para celebrar el fin de las luchas civiles. Representa la unidad entre plebeyos y patricios, esencial para la supervivencia de Roma. Se ofrecen sacrificios para mantener la paz interna." },
    "0-17": { status: 'C', statusFull: "Dies Comitialis", deity: "Felicitas", deityDesc: "Felicidad pública.", festivalName: "Día de Felicitas Publica", festivalDesc: "Ritos pro-bono a la Felicidad del Estado Romano. Los magistrados agradecen por la buena suerte colectiva que Roma disfruta sobre sus enemigos." },
    "0-18": { status: 'C', statusFull: "Dies Comitialis", deity: "Prisca", deityDesc: "Virtud antigua.", festivalName: "Día de la Virtud Prisca", festivalDesc: "Un recordatorio del 'Mos Maiorum' o las costumbres de los ancestros. Las asambleas comiciales debaten inspiradas por las glorias morales pasadas." },
    "0-19": { status: 'C', statusFull: "Dies Comitialis", deity: "Venus", deityDesc: "Venus.", festivalName: "Día Cívico de Venus", festivalDesc: "Venus asegura la harmonía, no solo en el amor, sino en la polis. Los ciudadanos buscan su gracia civil para evitar sediciones." },
    "0-20": { status: 'C', statusFull: "Dies Comitialis", deity: "Sanctitas", deityDesc: "Santidad.", festivalName: "Día de Sanctitas", festivalDesc: "Dedicado a la santidad intrínseca de los ritos y tabúes que componen el estado. Refuerza las leyes divinas no escritas de la urbe." },
    "0-21": { status: 'C', statusFull: "Dies Comitialis", deity: "Sancus", deityDesc: "Lealtad.", festivalName: "Reconocimiento a Sancus", festivalDesc: "Conmemoración del dios de los juramentos solemnes, Semo Sancus. Se verifica la lealtad y los tratados con aliados (Foedera)." },
    "0-22": { status: 'C', statusFull: "Dies Comitialis", deity: "Fides", deityDesc: "Fe.", festivalName: "Día de Fides", festivalDesc: "La buena Fe, soporte de todas las transacciones comerciales. Roma paralizaría su poderío mercantil si no se venerara a Fides diariamente." },
    "0-23": { status: 'C', statusFull: "Dies Comitialis", deity: "Diana", deityDesc: "Diana.", festivalName: "Día de Diana", festivalDesc: "Las asambleas se celebran bajo el amparo de la cazadora divina, protectora especial de la plebe y de los límites sagrados de los nemorales." },
    "0-24": { status: 'C', statusFull: "Dies Comitialis", deity: "Ceres y Tellus", deityDesc: "Siembra y Tierra.", festivalName: "Sementivae / Paganalia", festivalDesc: "Festival rural de la siembra (feriae sementivae). Se invoca a Ceres y a Tellus para que protejan las semillas recién plantadas del frío y las alimañas. Los bueyes son adornados y descansan del yugo. Es crucial para asegurar el pan del año siguiente." },
    "0-25": { status: 'C', statusFull: "Dies Comitialis", deity: "Ceres", deityDesc: "Agricultura.", festivalName: "Sementivae", festivalDesc: "Continúan los ritos de purificación de los campos. Se ofrece una cerda preñada (porca praecidanea) a Ceres. La comunidad se une para bendecir la tierra dormida bajo el invierno." },
    "0-26": { status: 'C', statusFull: "Dies Comitialis", deity: "Tellus", deityDesc: "Tierra.", festivalName: "Sementivae", festivalDesc: "Conclusión de las fiestas de la siembra, honrando a la Madre Tierra. Se pide que la tierra sea fértil y acoja con benevolencia el grano. La paz del campo es sagrada en estos días." },
    "0-27": { status: 'C', statusFull: "Dies Comitialis", deity: "Castor y Pólux", deityDesc: "Dióscuros.", festivalName: "Dedicación Templo Castor", festivalDesc: "Aniversario del Templo de Cástor y Pólux en el Foro Romano. Se recuerda su ayuda milagrosa en la Batalla del Lago Regilo. Los caballeros romanos honran a sus patronos divinos con desfiles y ofrendas. Símbolo de la protección divina sobre la caballería romana." },
    "0-28": { status: 'C', statusFull: "Dies Comitialis", deity: "Indiges", deityDesc: "Espíritus locales.", festivalName: "Honra a Indiges", festivalDesc: "Las asambleas invocan a los Di Indigetes, espíritus heroicos fundacionales, tales como el propio Eneas bajo el nombre de Júpiter Indiges." },
    "0-29": { status: 'F', statusFull: "Dies Fastus", deity: "Pax", deityDesc: "Paz.", festivalName: "Ara Pacis", festivalDesc: "Dedicación del Altar de la Paz Augusta (Ara Pacis). Se celebra la paz garantizada por el emperador y la prosperidad que trae consigo. Es un monumento a la Pax Romana, el orden y la abundancia sin guerra." },
    "0-30": { status: 'F', statusFull: "Dies Fastus", deity: "Salus", deityDesc: "Salud.", festivalName: "Día Fasto de la Salud", festivalDesc: "Los juicios prosiguen en los tribunales con normalidad tras los disturbios festivos, encomendando la seguridad o Salus Pública a las magistraturas." },
