    "1-27": { status: 'NP', statusFull: "Equirria", deity: "Mars", deityDesc: "Marte.", festivalName: "Equirria", festivalDesc: "Primeras carreras de caballos del año en el Campo de Marte para preparar a la caballería antes del comienzo de la temporada militar." },
    "1-28": { status: 'C', statusFull: "Dies Comitialis", deity: "Silvano", deityDesc: "Bosques.", festivalName: "Día Cívico del Bosque", festivalDesc: "Los campos rústicos despiertan. Los tribunales en Roma emiten edictos sobre límites madereros, pidiendo licencias al agreste Silvano protector." },
