    "2-4": { status: 'C', statusFull: "Dies Comitialis", deity: "Minerva", deityDesc: "Diosa de la estrategia.", festivalName: "Reunión Estratégica", festivalDesc: "Los magistrados congregan asambleas al abrigo de Minerva; se requiere sabiduría militar y pericia técnica sobre pasiones brutas." },
