    "2-6": { status: 'C', statusFull: "Dies Comitialis", deity: "Vesta", deityDesc: "Diosa del hogar.", festivalName: "Asamblea Familiar de Vesta", festivalDesc: "Raramente conectada a lo comicial per se, Vesta garantiza que el orden del hogar se traslade metafóricamente al orden estatal sin disputas." },
