    "2-8": { status: 'F', statusFull: "Dies Fastus", deity: "Ariane", deityDesc: "Diosa ctónica.", festivalName: "Ariadna Ctónica", festivalDesc: "Día para ritos privados y aperturas rápidas en tribunales bajo influencias antiquísimas (Ariadna como potencia ctónica vinculada al laberíntico rito agrario y báquico)." },
